impl WriteAdapter for Model802StatefulAdapter {
    /// Max Reserve Percent (SocRsvMax)
    ///
    /// Setpoint for maximum reserve for storage as a percentage of the nominal maximum storage.
    fn set_max_reserve_percent(&mut self, value: u16) {
        self.max_reserve_percent = value;
    }

    /// Min Reserve Percent (SoCRsvMin)
    ///
    /// Setpoint for minimum reserve for storage as a percentage of the nominal maximum storage.
    fn set_min_reserve_percent(&mut self, value: u16) {
        self.min_reserve_percent = value;
    }

    /// Controller Heartbeat (CtrlHb)
    ///
    /// Value is incremented every second with periodic resets to zero.
    fn set_controller_heartbeat(&mut self, value: u16) {
        self.controller_heartbeat = value;
    }

    /// Alarm Reset (AlmRst)
    ///
    /// Used to reset any latched alarms. 1 = Reset.
    ///
    /// Battery should reset to 0 when reset is complete.
    fn set_alarm_reset(&mut self, value: u16) {
        self.alarm_reset = value;
    }

    /// Set Operation (SetOp)
    ///
    /// Instruct the battery bank to perform an operation such as connecting. Enumeration.
    fn set_operation(&mut self, value: SetOp) {
        self.operation = value;
    }

    /// Set Inverter State (SetInvState)
    ///
    /// Set the current state of the inverter.
    ///
    /// Information needed by battery for some operations.
    fn set_inverter_state(&mut self, value: SetInvState) {
        self.inverter_state = value;
    }
}

/// C-FFI dispatch descriptor for SunSpec model 802. A C `SunspecModelBinding` points
/// at this static, so the service functions dispatch with no model-id lookup.
#[unsafe(no_mangle)]
pub static SUNSPEC_MODEL_802: StaticModelSpec = StaticModelSpec {
    id: 802,
    length: model_802_c_length,
    writable: true,
    visit_read: model_802_c_visit_read,
    visit_write: model_802_c_visit_write,
};

fn model_802_c_length(_repeat_count_0: u16, _repeat_count_1: u16) -> u16 {
    (Model802).model_length()
}

/// # Safety
/// For `kind` 1 or 2, `adapter` must point to a live `Model802{Stateful,Callback}Adapter`,
/// valid for the duration of the call.
unsafe fn model_802_c_visit_read(
    kind: u8,
    adapter: *const c_void,
    _repeat_count_0: u16,
    _repeat_count_1: u16,
    cursor: &mut Cursor<ModbusException>,
    buffer: &mut WritableRegisterBuffer<'_>,
) {
    let model = Model802;
    let adapter: Option<&dyn ReadAdapter> = match kind {
        1 => Some(unsafe { &*(adapter as *const Model802StatefulAdapter) } as &dyn ReadAdapter),
        2 => Some(unsafe { &*(adapter as *const Model802CallbackAdapter) } as &dyn ReadAdapter),
        _ => None,
    };
    cursor.visit_source_block(model.model_length(), |offset, from, len| {
        let mut block = buffer.slice(from, len);
        match adapter {
            Some(adapter) => model.traverse_points_read(adapter, &mut block, offset),
            None => {
                block.fill(&[0xff, 0xff]);
                Ok(())
            }
        }
    });
}

/// # Safety
/// As for [`model_802_c_visit_read`], and `adapter` must be uniquely borrowable for the call.
unsafe fn model_802_c_visit_write(
    kind: u8,
    adapter: *mut c_void,
    _repeat_count_0: u16,
    _repeat_count_1: u16,
    cursor: &mut Cursor<ModbusException>,
    buffer: &ReadableRegisterBuffer<'_>,
) {
    let model = Model802;
    let adapter: Option<&mut dyn WriteAdapter> = match kind {
        1 => {
            Some(unsafe { &mut *(adapter as *mut Model802StatefulAdapter) } as &mut dyn WriteAdapter)
        }
        2 => {
            Some(unsafe { &mut *(adapter as *mut Model802CallbackAdapter) } as &mut dyn WriteAdapter)
        }
        _ => None,
    };
    cursor.visit_source_block(model.model_length(), |offset, from, len| match adapter {
        Some(adapter) => model.traverse_points_write(adapter, &buffer.slice(from, len), offset),
        None => Err(ModbusException::IllegalDataAddress),
    });
}
